{
 "requirements": [
  {
   "id": "R1",
   "text": "Write the expression grammar (precedence and associativity rules)."
  },
  {
   "id": "R2",
   "text": "Hand-written lexer producing tokens with line and column."
  },
  {
   "id": "R3",
   "text": "Recursive-descent parser that builds an AST."
  },
  {
   "id": "R4",
   "text": "Evaluator that walks the AST."
  },
  {
   "id": "R5",
   "text": "Syntax errors reported with line and column, continuing with the next line."
  },
  {
   "id": "R6",
   "text": "File of at least 20 test expressions with expected outputs."
  },
  {
   "id": "R7",
   "text": "One-page explanation of the grammar."
  }
 ],
 "constraints": [
  "no parser generators",
  "C, C++, Java or Python"
 ],
 "deliverables": [
  "source code",
  "test expression file",
  "grammar explanation"
 ],
 "notes": "The parser is derived from the grammar and consumes the lexer's tokens; the evaluator walks the parser's AST; the explanation document describes the final grammar."
}

